<!-- ===================== Firebase + form submit script (kept) ===================== -->
<script src="https://www.gstatic.com/firebasejs/8.10.1/firebase-app.js"></script>
<script src="https://www.gstatic.com/firebasejs/8.10.1/firebase-database.js"></script>
<script src="/php-duhoc/public/assets/js/firebase-config.js"></script>

<script>
document.addEventListener('DOMContentLoaded', function() {
  const form = document.getElementById('consultation-form');

  if (form) {
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      const btn = form.querySelector('button[type="submit"]');
      const formData = new FormData(this);

      fetch('/php-duhoc/public/consultation/register', {
        method: 'POST',
        body: formData
      })
      .then(r => r.json())
      .then(data => {
        if (data.success) {
          alert(data.message);

          if (typeof firebase !== 'undefined') {
            const newRef = firebase.database().ref('notifications').push();
            newRef.set({
              type: 'new_consultation',
              data: {
                name: formData.get('full_name'),
                phone: formData.get('phone'),
                email: formData.get('email'),
                message: formData.get('message')
              },
              timestamp: firebase.database.ServerValue.TIMESTAMP,
              read: false
            });
          }

          form.reset();
        } else {
          alert(data.message);
        }
      })
      .catch(err => {
        console.error(err);
        alert('Có lỗi xảy ra khi gửi đăng ký.');
      });
    });
  }
});
</script>

</body>
</html>
